INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'python', 'advanced', 'In the Pulumi infrastructure-as-code example, what does pulumi.export() do?', '["It deletes the named resource from the stack", "It exposes a stack output value (like a VPC ID or generated kubeconfig) so other stacks or external tooling can reference it after the deployment completes", "It exports the entire Python script as a standalone executable", "It converts the Pulumi program from Python to a different supported language"]', 1, 'pulumi.export() publishes named output values from a stack -- exactly like the vpc_id, cluster_name, and generated kubeconfig in the example -- making them available for other stacks or tooling to consume after deployment.', 'intermediate'),
('devops', 'python', 'advanced', 'What does asyncio.Semaphore(concurrency) control in the 500-server parallel command script?', '["It sets the total number of servers the script is allowed to target", "It caps how many SSH connections run concurrently at once (e.g. 50), regardless of how many total hosts (500) are being processed -- preventing the script from opening all 500 connections simultaneously", "It controls how many times a failed connection is retried", "It sets a global timeout for the entire script''s execution"]', 1, 'The semaphore limits concurrent in-flight operations to the configured value (50) even though gather() is called against all 500 hosts at once -- bounding resource usage (open connections) rather than letting every host connect simultaneously.', 'advanced'),
('devops', 'python', 'advanced', 'Why does run_on_server catch exceptions and return a ServerResult with success=False, rather than letting the exception propagate up through asyncio.gather?', '["Because asyncio.gather cannot technically handle any exceptions at all", "So one server''s connection failure doesn''t crash the entire batch -- gather() collects a result (success or failure) per host, letting the script report exactly which of the 500 servers failed and why, instead of aborting on the first failure", "Because Python''s asyncio library requires all coroutines to always return successfully", "To make the script run measurably faster by skipping error handling overhead"]', 1, 'Catching the exception inside run_on_server and encoding failure in the returned ServerResult means one bad host doesn''t abort the whole batch -- the script can report exactly which hosts failed (and why) after gather() completes, rather than stopping at the first error.', 'advanced'),
('devops', 'python', 'advanced', 'What does the @observe_request decorator automatically add to any function it wraps?', '["It automatically retries the function up to 3 times on failure", "Distributed tracing (a span) and metrics (a request counter and latency histogram) around the function call, recording success/error status and duration without the function''s own code needing to do any of that manually", "It converts the function into an asynchronous coroutine automatically", "It caches the function''s return value for repeated calls with the same arguments"]', 1, 'The decorator wraps a function with a tracer span and records both a counter (success/error, tagged by function name) and a latency histogram -- giving automatic tracing and metrics to any decorated function, like deploy_service, with zero instrumentation code inside it.', 'intermediate'),
('devops', 'python', 'advanced', 'Why is RequestsInstrumentor().instrument() called once at application startup rather than wrapping each individual HTTP call?', '["Because OpenTelemetry only allows one instrumentation call per Python process for licensing reasons", "It patches the requests library globally at import/startup time, so every HTTP call made anywhere in the application afterward is automatically traced -- without needing to manually instrument each individual call site", "Because calling it per-request would exceed Python''s maximum recursion depth", "It has no functional difference from calling it before each request; it''s purely a style preference"]', 1, 'Auto-instrumentation patches the library once, globally -- every subsequent HTTP call through that library is automatically traced afterward, avoiding the need to manually wrap every single call site throughout the codebase.', 'intermediate'),
('devops', 'shell-scripting', 'fundamentals', 'What is the difference between echo "$name" and echo ''$name'' in bash?', '["There is no difference -- both print the literal text $name", "Double quotes expand the variable to its value; single quotes treat the text literally, printing $name as-is without expansion", "Single quotes expand the variable; double quotes treat it literally", "Both syntaxes cause a syntax error in bash"]', 1, 'Double quotes allow variable expansion (echo "$name" prints the value of $name), while single quotes suppress all expansion, printing the literal characters $name -- a distinction that matters constantly in real scripts.', 'beginner'),
('devops', 'shell-scripting', 'fundamentals', 'What does ${1:-World} evaluate to when a script is run with no arguments at all?', '["It causes the script to exit immediately with an error", "It evaluates to the string ''World'' -- the default value after the colon-dash is used when the first positional argument ($1) is unset or empty", "It evaluates to an empty string with no error", "It always evaluates to the literal text ''${1:-World}'' unmodified"]', 1, '${1:-World} is parameter expansion with a default: if $1 is unset (no argument given), it evaluates to ''World''; if $1 is set, it uses that value instead -- exactly the pattern shown in the greet.sh ''Try It'' example.', 'beginner'),
('devops', 'shell-scripting', 'fundamentals', 'In a bash conditional, what is the difference between -eq and == ?', '["They are interchangeable in every context with no difference at all", "-eq is used for numeric comparison (e.g. [[ $count -eq 0 ]]); == is used for string comparison (e.g. [[ \"$env\" == \"production\" ]])", "== is only valid inside double brackets; -eq is only valid inside single brackets", "-eq compares file timestamps; == compares file permissions"]', 1, 'The fundamentals content lists -eq/-ne/-lt/-le/-gt/-ge specifically for numeric comparisons and == for string comparisons -- using the wrong one for the data type being compared is a common bash scripting bug.', 'intermediate'),
('devops', 'shell-scripting', 'fundamentals', 'In `while IFS= read -r line; do echo "Line: $line"; done < /etc/hosts`, why are IFS= and -r used together?', '["They have no real effect and are included purely as a style convention", "IFS= prevents leading/trailing whitespace from being stripped from each line, and -r prevents backslash characters from being interpreted as escape sequences -- together they read each line exactly as it appears in the file", "IFS= sets the input file''s character encoding; -r makes the loop run in reverse order", "-r causes the loop to only read the first line of the file, ignoring the rest"]', 1, 'This is the standard ''safe'' file-reading pattern: IFS= preserves whitespace that would otherwise be trimmed by word-splitting, and -r stops read from treating backslashes as escapes -- together giving a faithful, unmodified read of each line.', 'advanced'),
('devops', 'shell-scripting', 'fundamentals', 'What does `set -euo pipefail` do collectively at the top of a bash script?', '["It enables verbose debug output for every command executed", "-e exits the script on any command failure, -u errors on use of an undefined variable, and -o pipefail makes a pipeline fail if any command within it fails (not just the last one) -- together, a much stricter, safer default than bash''s normal behavior", "It silences all error messages so the script runs without any visible output", "It causes the script to automatically retry any failed command up to 3 times"]', 1, 'These three options combined are the standard ''strict mode'' for production bash scripts: exit on error, error on undefined variables, and propagate failure through a pipeline -- catching classes of silent bugs bash otherwise tolerates by default.', 'intermediate'),
('devops', 'shell-scripting', 'intermediate', 'In the deployment script''s backup_current function, what does `ls -dt "$BACKUP_DIR"* | tail -n +4 | xargs rm -rf` accomplish?', '["It deletes all backups immediately after creating a new one", "It lists backups newest-first, skips the 3 most recent (tail -n +4), and deletes the rest -- keeping only the last 3 backups on disk", "It compresses all backup directories into a single archive file", "It renames all existing backups sequentially by date"]', 1, 'ls -dt sorts backups newest-first; tail -n +4 skips the first 3 (the newest), passing only older backups beyond that to rm -rf -- a rolling retention pattern that keeps exactly the 3 most recent backups.', 'intermediate'),
('devops', 'shell-scripting', 'intermediate', 'Why does the process-management example capture $! (PID=$!) immediately after backgrounding a command with &?', '["$! is required syntax and has no functional purpose", "$! holds the process ID of the most recently backgrounded job, letting the script later call wait $PID to block until that specific background job finishes and check its exit code", "$! generates a random temporary filename for the command''s output", "$! is a bash built-in that immediately kills the backgrounded process"]', 1, '$! captures the PID of the just-started background job -- necessary because without saving it immediately, there''s no reliable way to later wait on or check the exit status of that specific background process among potentially several.', 'intermediate'),
('devops', 'shell-scripting', 'intermediate', 'What is the difference between ${filename%.csv} and ${filename##*.} for filename="report_2024-01-15.csv"?', '["They produce identical output in all cases", "${filename%.csv} strips the exact suffix ''.csv'' from the end, giving ''report_2024-01-15''; ${filename##*.} strips everything up to and including the last dot, giving just the extension ''csv''", "${filename%.csv} deletes the file from disk; ${filename##*.} only renames it", "Both operators only work on numeric variables, not strings"]', 1, '%.csv removes a specific trailing suffix, leaving the filename without it; ##*. greedily removes everything up to the last dot, leaving only what comes after it (the extension) -- two different parameter-expansion operations for two different extraction goals.', 'intermediate'),
('devops', 'shell-scripting', 'intermediate', 'Why does the nginx config heredoc use a quoted delimiter (''NGINX_EOF'') while the .env example uses an unquoted delimiter (ENV_EOF)?', '["The choice is purely stylistic and has no effect on the heredoc''s behavior", "A quoted delimiter (''NGINX_EOF'') prevents variable expansion inside the heredoc, keeping literal $host in the nginx config; an unquoted delimiter (ENV_EOF) allows variables like ${DB_USER} to expand to their actual values before being written to the file", "A quoted delimiter makes the heredoc read-only; an unquoted one makes it writable", "Quoted delimiters are required for multi-line content; unquoted delimiters only support single-line content"]', 1, 'The nginx config needs $host to remain literal (it''s an NGINX variable, not a bash one), so the quoted delimiter suppresses bash expansion; the .env file needs actual bash variable values substituted in, so the unquoted delimiter allows that expansion to happen.', 'advanced'),
('devops', 'shell-scripting', 'intermediate', 'In the disk-space-check script, what does `done < <(df -h | grep -E ''^/dev/'')` (process substitution feeding the while loop) achieve that a regular pipe (`df -h | grep ... | while ...`) would not?', '["It makes the script run measurably faster by avoiding process creation entirely", "Process substitution keeps the while loop running in the current shell (not a subshell), so variables set or modified inside the loop persist after the loop finishes -- unlike piping into a while loop, where the loop runs in a subshell and any variable changes are lost once it exits", "It converts the loop from a while loop into a for loop automatically", "It changes the loop from processing lines to processing individual characters"]', 1, 'Piping into a while loop runs the loop body in a subshell (bash creates a subshell for each pipeline stage), so any variable set inside is lost when the loop ends; process substitution avoids that subshell, keeping the loop in the current shell so its side effects persist.', 'advanced'),
('devops', 'shell-scripting', 'advanced', 'What does process substitution (`diff <(ssh server1 ''cat /etc/passwd'') <(ssh server2 ''cat /etc/passwd'')`) let you do that a regular pipe cannot?', '["It lets diff run without needing any input at all", "It lets diff (a command expecting two file arguments) compare the live output of two separate commands directly, by presenting each command''s output as if it were a temporary file -- without manually writing either output to disk first", "It automatically fixes any differences found between the two outputs", "It runs both SSH commands on the exact same remote server simultaneously"]', 1, 'Process substitution (<(...)) presents a command''s output as a file-like path that diff (which expects two file arguments, not piped input) can read directly -- letting two live command outputs be compared without manually saving either to a temp file first.', 'advanced'),
('devops', 'shell-scripting', 'advanced', 'In the parallel job-control example, what does `while [[ $(jobs -r | wc -l) -ge $MAX_JOBS ]]; do sleep 0.5; done` accomplish before launching each new background deployment?', '["It cancels all currently running background jobs before starting a new one", "It throttles concurrency -- pausing before starting a new background job if the number of currently running jobs already meets or exceeds MAX_JOBS, preventing the script from launching unbounded parallel deployments all at once", "It counts how many servers have already been successfully deployed to", "It converts the parallel deployment loop into a purely sequential one"]', 1, 'This is a manual concurrency limiter: before backgrounding another deploy_to_server call, the script checks the current running-job count and waits if it''s already at MAX_JOBS -- bounding parallelism instead of firing off every server''s deployment simultaneously.', 'advanced'),
('devops', 'shell-scripting', 'advanced', 'What does `flock -n 9` accomplish in the configuration script, and what happens if another instance is already running?', '["It compresses file descriptor 9 to save disk space", "It attempts to acquire an exclusive, non-blocking lock on file descriptor 9 (tied to the lock file); if another instance already holds the lock, flock -n fails immediately rather than waiting, which triggers die \"Another instance is already running\"", "It forcibly terminates any other running instance of the script automatically", "It creates a backup of file descriptor 9''s contents before proceeding"]', 1, 'flock -n attempts a non-blocking exclusive lock -- if the lock is already held (another instance running), it fails immediately instead of waiting, and the || die pattern turns that failure into an explicit, clear exit rather than two instances running concurrently and corrupting shared state.', 'advanced'),
('devops', 'shell-scripting', 'advanced', 'In the ROLLBACK_ACTIONS array pattern, why does the rollback function iterate from the last index down to 0, rather than forward from 0?', '["Iterating backward is purely a style choice with no functional reason", "Rollback actions must be undone in the reverse order they were applied -- the most recently completed step should be undone first, since later steps may depend on earlier ones still being in their original (pre-change) state", "Bash arrays can only be iterated in reverse order; forward iteration is not supported", "Forward iteration would cause the script to enter an infinite loop"]', 1, 'Rolling back in reverse mirrors how the changes were applied -- undoing the most recent action first is necessary because it may have been built on top of an earlier action''s changes, so undoing in forward order could attempt to roll back a step whose dependencies were already reverted.', 'advanced'),
('devops', 'shell-scripting', 'advanced', 'What do `trap rollback ERR` and `trap cleanup EXIT` achieve together in the configuration script?', '["They have no combined effect; only one trap can be active in a script at a time", "trap ... ERR automatically triggers the rollback function if any command fails (thanks to set -e), while trap ... EXIT ensures cleanup (releasing the lock, removing the lock file) always runs when the script exits, whether it succeeded, failed, or was rolled back", "Both traps do the exact same thing and are redundant with each other", "They disable all error handling for the remainder of the script"]', 1, 'The two traps handle different responsibilities: ERR specifically triggers rollback logic on command failure (working with set -e), while EXIT guarantees cleanup (lock release, lock file removal) runs on every exit path -- success, failure, or after rollback -- so the lock is never left stuck.', 'advanced')
